371	/**
372	 * Request body schema for POST /api/model-assignments/replace.
373	 */
374	const ReplaceModelBodySchema = z
375	  .object({
376	    old_model_id: z.string().uuid(),
377	    new_model_id: z.string().uuid(),
378	  })
