380	
381	/**
382	 * Swaps all occurrences of `old_model_id` with `new_model_id` in the current
383	 * assignments.
384	 *
385	 * Rejects with 400 when:
386	 * - `old_model_id === new_model_id`
387	 * - `old_model_id` is not currently referenced in any assignment
388	 *
389	 * Both UUIDs must exist in the model registry.
390	 *
391	 * @param body - Raw parsed JSON request body.
392	 */
393	export async function handleReplaceAssignedModel(
394	  body: unknown
395	): Promise<ModelAssignments> {
396	  const parsed = ReplaceModelBodySchema.safeParse(body);
397	  if (!parsed.success) {
398	    validationError(
399	      `Invalid replace body: ${parsed.error.issues.map((i) => i.message).join('; ')}`
400	    );
401	  }
402	
403	  const { old_model_id, new_model_id } = parsed.data;
404	
405	  // Reject same-model replacement
406	  if (old_model_id === new_model_id) {
407	    validationError('Source and target models must be different.');
408	  }
409	
410	  // Validate both UUIDs exist in the registry
411	  const models = await readModels();
412	  const validModelIds = new Set(models.map((m) => m.id));
413	
414	  if (!validModelIds.has(old_model_id)) {
415	    validationError(
416	      `old_model_id "${old_model_id}" does not exist in the model registry.`
417	    );
418	  }
419	
420	  if (!validModelIds.has(new_model_id)) {
421	    validationError(
422	      `new_model_id "${new_model_id}" does not exist in the model registry.`
423	    );
424	  }
425	
426	  // Load current assignments
427	  const assignments = await readAssignments();
428	
429	  // Check that old_model_id is actually referenced
430	  let referenced = false;
431	  if (assignments.default_model_uuid === old_model_id) {
432	    referenced = true;
433	  }
434	  for (const uuid of Object.values(assignments.persona_models)) {
435	    if (uuid === old_model_id) {
436	      referenced = true;
437	      break;
438	    }
439	  }
440	
441	  if (!referenced) {
442	    validationError(
443	      `Model "${old_model_id}" is not referenced in any current assignment. Nothing to replace.`
444	    );
445	  }
446	
447	  // Perform the swap
448	  const updated: ModelAssignments = {
449	    default_model_uuid:
450	      assignments.default_model_uuid === old_model_id
451	        ? new_model_id
452	        : assignments.default_model_uuid,
453	    persona_models: Object.fromEntries(
454	      Object.entries(assignments.persona_models).map(([k, v]) => [
455	        k,
456	        v === old_model_id ? new_model_id : v,
457	      ])
458	    ),
459	  };
460	
461	  await writeAssignments(updated);
462	  return updated;
463	}
