143	/**
144	 * Validates and writes `models` to `local.json` atomically.
145	 *
146	 * Guards:
147	 * 1. Schema validation — all entries must conform to `ModelEntrySchema`.
148	 * 2. Slug uniqueness — duplicate slugs are rejected.
149	 * 3. Reserved slug — the slug `"inherit"` is only permitted on the sentinel entry
150	 *    whose UUID is `00000000-0000-0000-0000-000000000000`.
151	 * 4. Deletion guard — entries present in the current `local.json` but absent from
152	 *    `models` are treated as deletions.  If any deleted model's UUID is referenced
153	 *    in `assignments.json`, the write is rejected and the caller receives the list
154	 *    of usages so they can surface them to the user.
155	 *    - If `local.json` does not yet exist (or is inaccessible due to an OS-level
156	 *      error such as permission denied), the guard is skipped and the write proceeds.
157	 *    - If `local.json` exists but is corrupt (parse failure or schema mismatch), the
158	 *      write is rejected with an `ApiError` (`PARSE_ERROR` or `VALIDATION_ERROR`);
159	 *      corruption must be resolved before any modifications are permitted.
160	 *
161	 * Returns `{ saved: true, models: ModelEntry[] }` on success, or
162	 * `{ saved: false, referencedModels: ReferencedModel[] }` when a deletion is blocked.
163	 *
164	 * @throws {ApiError} with code `VALIDATION_ERROR` on schema or constraint violations.
165	 * @throws {ApiError} with code `PARSE_ERROR` or `VALIDATION_ERROR` when `local.json`
166	 *   exists but cannot be parsed or fails schema validation (corruption guard).
167	 * @throws {ApiError} with code `WRITE_ERROR` if the atomic write to `local.json` fails.
168	 */
169	export type WriteModelsResult =
170	  | { saved: true; models: ModelEntry[] }
171	  | { saved: false; referencedModels: ReferencedModel[] };
172	
173	export interface ReferencedModel {
174	  model: ModelEntry;
175	  usages: string[];
176	}
177	
178	export async function writeModels(models: ModelEntry[]): Promise<WriteModelsResult> {
179	  // 1. Schema validation
180	  const validation = ModelRegistrySchema.safeParse(models);
181	  if (!validation.success) {
182	    throw new ApiError(
183	      'VALIDATION_ERROR',
184	      `Model list failed schema validation: ${validation.error.message}`
185	    );
186	  }
187	  const validated = validation.data;
188	
189	  // 2. Slug uniqueness
190	  const slugsSeen = new Set<string>();
191	  for (const entry of validated) {
192	    if (slugsSeen.has(entry.slug)) {
193	      throw new ApiError(
194	        'VALIDATION_ERROR',
195	        `Duplicate slug detected: "${entry.slug}". Each model must have a unique slug.`
196	      );
197	    }
198	    slugsSeen.add(entry.slug);
199	  }
200	
201	  // 3. Reserved slug guard
202	  for (const entry of validated) {
203	    if (entry.slug === RESERVED_SLUG && entry.id !== INHERIT_SENTINEL_UUID) {
204	      throw new ApiError(
205	        'VALIDATION_ERROR',
206	        `The slug "${RESERVED_SLUG}" is reserved for the built-in "Inherit / Auto" model and cannot be used for other entries.`
207	      );
208	    }
209	  }
210	
211	  // 4. Deletion guard — identify removed model IDs
212	  let existingModels: ModelEntry[] = [];
213	  try {
214	    existingModels = await readModels();
215	  } catch (err) {
216	    // Silently skip the deletion guard only for OS-level read failures (e.g. file
217	    // not found, permission denied) — these mean there is nothing to protect.
218	    // Any ApiError from a corrupt local.json (PARSE_ERROR, VALIDATION_ERROR) is
219	    // re-thrown so the caller cannot inadvertently bypass the guard on bad data.
220	    if (!(err instanceof ApiError && err.code === 'READ_ERROR') && !(isNodeError(err) && err.code === 'ENOENT')) {
221	      throw err;
222	    }
223	  }
224	
225	  const incomingIds = new Set(validated.map((m) => m.id));
226	  const deletedModels = existingModels.filter((m) => !incomingIds.has(m.id));
227	
228	  if (deletedModels.length > 0) {
229	    const referencedModels: ReferencedModel[] = [];
230	    for (const model of deletedModels) {
231	      const ref = await isModelReferenced(model.id);
232	      if (ref.referenced) {
233	        referencedModels.push({ model, usages: ref.usages });
234	      }
235	    }
236	    if (referencedModels.length > 0) {
237	      return { saved: false, referencedModels };
238	    }
239	  }
240	
241	  // 5. Write
242	  await atomicWriteJson(localJsonPath(), validated);
243	  return { saved: true, models: validated };
244	}
